+func setRoutingField(item map[string]interface{}, key, columnValue string, logger *zap.Logger) {
+	if columnValue != "" {
+		item[key] = columnValue
+		return
+	}
+	spec, ok := item["spec"].(map[string]interface{})
+	if !ok {
+		return
+	}
+	if fromSpec, present := spec[key].(string); present && fromSpec != "" {
+		item[key] = fromSpec
+		return
+	}
+	if raw, present := spec[key]; present {
+		logger.Warn("LoadWorkItemsAction: spec key is not a non-empty string — routing field left unset",
+			zap.String("key", key), zap.String("spec_type", fmt.Sprintf("%T", raw)))
+	}
+}

BEGIN;
-- snapshot input_mapping first (exact rollback, not a reconstructed one)
UPDATE agent_definitions
SET default_config = jsonb_set(default_config,
      '{workflow,steps,process_item,config,sub_workflow,steps,call_handler,config,input_mapping,component_id?}',
      '"current_item.component_id"'::jsonb, false)
WHERE type='build-dispatch-loop' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL
  AND default_config #>> '{...,input_mapping,component_id?}' = 'current_item.spec.component_id';
COMMIT;

The key carries the '?' — it is the optional marker and part of the JSON key. (Distinct from bugs_open/134, where a '?' leaked into a params key, where it means nothing and makes the key inert.) Rollback is the same statement inverted, in the file.
